pub fn put(&mut self, key: K, value: V) -> Option<V> {
    if let Some(&i) = self.map.get(&key) {
        self.unlink(i);
        let old = std::mem::replace(&mut self.nodes[i].value, value);
        // key unchanged
        self.attach_head(i);
        return Some(old);
    }
    if self.len == self.capacity {
        // Evict LRU
        let t = self.tail.unwrap(); // len == capacity > 0 so cache is full
        self.remove_node(t);
    }
    self.insert_head(key, value);
    None
}
```

